'use strict';
const C=window.CONTENT, QB=window.QUESTION_BANK, $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>/^https:\/\//.test(s)?esc(s):'#';
const bn=n=>Number(n).toLocaleString('bn-BD'), date=s=>new Date(s).toLocaleDateString('bn-BD',{year:'numeric',month:'short',day:'numeric'});
const KEY='campus-companion.v1';
let data={saved:[],checks:[],attempts:[],session:null}, storageOK=true;
try{const d=JSON.parse(localStorage.getItem(KEY));if(d&&Array.isArray(d.saved)&&Array.isArray(d.checks)&&Array.isArray(d.attempts))data={...data,...d}}catch{storageOK=false}
try{const oldPlayer=JSON.parse(localStorage.getItem('campus-player'));if(oldPlayer&&!data.player)data.player=oldPlayer}catch{}
let universityFilter='all', timerID=null;
const topics=[...new Set(QB.map(q=>q.topic))];
const topicDescriptions={'Tense':'সময় ও verb form','Sequence of Tense':'Reported speech ও সময়ের সম্পর্ক','Mixed English':'Grammar ও vocabulary','Noun':'Countability ও noun forms','Article':'A, an, the ও zero article','Number':'Singular ও plural','Gender':'Gender vocabulary'};
const paths=[['practice','English MCQ Test','Topic বেছে timed test দাও'],['universities','University Guide','নিজের পছন্দের campus চিনে নাও'],['updates','Admission Updates','Official notice-এর ঠিকানা']];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{storageOK=false;toast('অগ্রগতি save হয়নি। Backup download করে রাখো।')}}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('toast').style.display='none',2800)}
function external(url,label){return `<a class="text-link" href="${safeURL(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}
function heading(title,desc,eyebrow='ADMISSION COMPANION'){return `<div class="page-head"><div class="breadcrumb"><a href="#home">হোম</a> / ${esc(title)}</div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>`}
function wrap(html){return `<div class="container">${html}</div>`}
function universityCard(u){return `<article class="card"><div class="university-cover"><b>${esc(u.short)}</b><span>${esc(u.type)}</span></div><h3>${esc(u.name)}</h3><span class="muted">${esc(u.place)}</span><p>${esc(u.text)}</p><a class="text-link" href="#university/${u.id}">View University Guide →</a></article>`}
function updateCard(u){return `<article class="card"><span class="tag">${esc(u.kind)} · ${esc(u.university)}</span><h3>${esc(u.title)}</h3><p>${esc(u.body)}</p><small class="muted">${esc(u.session)}</small>${external(u.url,'Official portal খুলুন')}</article>`}
function practiceSetup(){const player=data.player||{};return `<section class="card test-start"><span class="eyebrow">ENGLISH MCQ TEST</span><h2>English MCQ Test শুরু করো</h2><p class="muted">নাম, topic ও প্রশ্নসংখ্যা বেছে test শুরু করো।</p><div class="toolbar"><div class="field"><label for="player-name">তোমার পুরো নাম</label><input id="player-name" list="player-name-suggestions" maxlength="60" autocomplete="name" placeholder="যেমন: Misbahul Islam Tuhin" value="${esc(player.name||'')}"><datalist id="player-name-suggestions">${player.name?`<option value="${esc(player.name)}"></option>`:''}</datalist></div><div class="field"><label for="practice-topic">Topic</label><select id="practice-topic"><option value="all">সব topic (Mixed English)</option>${topics.map(t=>`<option value="${esc(t)}">${esc(t)} · ${bn(QB.filter(q=>q.topic===t).length)} প্রশ্ন</option>`).join('')}</select></div><div class="field"><label for="practice-count">কয়টি প্রশ্ন?</label><select id="practice-count"><option value="10">১০টি</option><option value="20" selected>২০টি</option><option value="30">৩০টি</option></select></div><button class="btn" data-start="test" type="button">Test শুরু করো →</button></div><p class="muted">সব উত্তর জমা দিলে answer key, explanation এবং কত সময় লেগেছে দেখাবে।</p></section>`}
function home(){return `<section class="hero"><div class="container"><span class="eyebrow">SBS STUDENTS’ ASSOCIATION</span><h1>English MCQ Test</h1><p>সহজে practice করো, নিজের score ও topic-এ position দেখো।</p>${data.player?.name?`<p class="profile-welcome">আবার স্বাগতম, <b>${esc(data.player.name)}</b>!</p>`:''}${practiceSetup()}</div></section><div class="container">${leaderboardPanel()}<section class="section study-tips"><div class="section-head"><div><h2>প্রস্তুতির ৪টি সহজ অভ্যাস</h2><p>প্রতিদিন অল্প অল্প করে, নিয়মিত revision।</p></div></div><div class="grid"><article class="card"><h3>১. আজকের পড়া আজই শেষ</h3><p>প্রতিদিনের class lecture ও notes ওই দিনই শেষ করো।</p></article><article class="card"><h3>২. আগের পড়া revise করো</h3><p>পরের দিন আগের topic আবার দেখো।</p></article><article class="card"><h3>৩. Previous questions solve করো</h3><p>বিভিন্ন বছরের প্রশ্ন বারবার solve করলে pattern বোঝা যায়। ভুলগুলো note করো।</p></article><article class="card"><h3>৪. সময় ধরে MCQ দাও</h3><p>ভর্তি পরীক্ষা একবারের সুযোগ—concept বুঝে প্রস্তুতি নাও, শুধু মুখস্থ নয়।</p></article></div></section><section class="section campus-shortcuts"><div class="section-head"><div><h2>চট্টগ্রাম ও ঢাকা বিশ্ববিদ্যালয়</h2><p>ইতিহাস, campus ও admission unit সম্পর্কে জানো।</p></div><a class="text-link" href="#universities">সব বিশ্ববিদ্যালয় →</a></div><div class="grid">${C.universities.filter(u=>['cu','du'].includes(u.id)).map(universityCard).join('')}</div></section></div>`}
function universities(){let list=C.universities.filter(u=>universityFilter==='all'||u.type===universityFilter);return wrap(heading('University Guide','চবি, ঢাবি এবং আরও কিছু বিশ্ববিদ্যালয়ের পরিচিতি ও প্রস্তুতির পথ। এটি বাংলাদেশের All Universitiesের পূর্ণ তালিকা নয়।','FIND YOUR CAMPUS')+`<div class="chips">${['all',...new Set(C.universities.map(u=>u.type))].map(x=>`<button class="chip ${universityFilter===x?'active':''}" data-university-filter="${esc(x)}">${x==='all'?'All Universities':esc(x)}</button>`).join('')}</div><div class="grid">${list.map(universityCard).join('')}</div><section class="section"><div class="notice">যোগ্যতা, ইউনিট, পরীক্ষাপদ্ধতি ও তারিখ academic session অনুযায়ী বদলাতে পারে। বর্তমান official circular-ই চূড়ান্ত তথ্যের উৎস।</div></section>`)}
let campusTab='overview';
const CAMPUS_IMAGE_DATA={cover:'data:image/webp;base64,',buildings:'data:image/webp;base64,'};
function campusPicture(name,alt,priority=false){const src=name==='cu-cover'?CAMPUS_IMAGE_DATA.cover:CAMPUS_IMAGE_DATA.buildings;return `<img class="campus-image" src="${src}" width="480" height="270" alt="${esc(alt)}" ${priority?'fetchpriority="high" loading="eager"':'loading="lazy"'} decoding="async">`}
function cuCampus(u){const p=u.campusStory;const tabs=[['overview','Overview'],['academics','Academics'],['life','Campus Life']];const indices=campusTab==='academics'?[2]:campusTab==='life'?[3,4,5]:[0,1,6];return `<section class="campus-hero"><div class="container campus-hero-grid"><div><a class="campus-back" href="#universities">University Guide / CU</a><span class="eyebrow">তোমার পরের ঠিকানা</span><h1>পাহাড়ের পাশে,<br>নতুন জীবনের শুরু।</h1><p>চট্টগ্রাম বিশ্ববিদ্যালয়<br><span>University of Chittagong</span></p><div class="actions"><button class="btn" data-campus-tab="academics">Explore Subjects →</button><button class="btn secondary" data-campus-tab="life">Campus Life →</button></div></div><div class="campus-cover">${campusPicture('cu-cover','চট্টগ্রাম বিশ্ববিদ্যালয়ের পাহাড়ঘেরা campus ও স্মৃতিস্তম্ভ; reference থেকে পুনর্নির্মিত ছবি',true)}<span class="photo-caption">চট্টগ্রাম বিশ্ববিদ্যালয় · Campus cover</span></div></div></section>${wrap(`<div class="campus-summary">${p.facts.slice(0,3).map(([h,t])=>`<div><small>${esc(h)}</small><b>${esc(t)}</b></div>`).join('')}</div><div class="campus-body"><aside class="campus-side"><small>EXPLORE CU</small><div role="tablist" aria-label="Campus sections">${tabs.map(([id,label])=>`<button type="button" role="tab" id="campus-tab-${id}" data-campus-tab="${id}" aria-selected="${campusTab===id}" aria-controls="campus-panel">${label}</button>`).join('')}</div><div class="campus-official"><small>OFFICIAL WEBSITES</small>${external('https://cu.ac.bd/','CU Official Website')}${external('https://admission.cu.ac.bd/','CU Admission Website')}</div></aside><div class="campus-main" id="campus-panel" role="tabpanel" aria-labelledby="campus-tab-${campusTab}">${campusTab==='overview'?`<p class="campus-intro">${esc(p.intro)}</p>`:''}${indices.map(i=>{const [label,h,t]=p.sections[i];return `<section><span class="eyebrow">${esc(label)}</span><h2>${esc(h)}</h2><p>${esc(t)}</p>${i===2?`<div class="subject-grid">${p.areas.map(([name,subjects])=>`<article><h3>${esc(name)}</h3><p>${esc(subjects)}</p></article>`).join('')}</div><p class="muted">কয়েকটি পরিচিত বিষয়ের উদাহরণ; সব department-এর পূর্ণ তালিকা নয়।</p>`:''}${i===4?`<figure class="campus-inline-photo">${campusPicture('cu-buildings','পাহাড়ের মাঝে চবির academic ভবন; reference থেকে পুনর্নির্মিত ছবি')}<figcaption>Reference থেকে পুনর্নির্মিত campus image</figcaption></figure>`:''}</section>`}).join('')}</div></div><div class="section"></div>`)}`}
function university(id){const u=C.universities.find(x=>x.id===id);if(!u)return missing();if(u.campusStory)return cuCampus(u);const d=u.details;return wrap(`<div class="reading university-reading"><a class="text-link" href="#universities">← All Universities</a>${heading(u.name,u.english,'UNIVERSITY GUIDE')}<p class="intro">${esc(u.text)}</p><div class="profile-tabs"><a href="#campus-location">Campus Location</a><a href="#admission-process">Admission Process</a><a href="#documents">Documents</a><a href="#official-sources">Sources</a></div><article><section id="campus-location"><h2>Campus Location & Geography</h2><dl class="campus-facts">${[['Division',d.division],['District',d.district],['Campus Address',d.address],['Surroundings',d.setting]].map(([h,t])=>`<div><dt>${h}</dt><dd>${esc(t)}</dd></div>`).join('')}</dl><p>${esc(d.geography)}</p>${external('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(u.english+' '+d.address),'Find Campus on Google Maps ↗')}<h3>Getting There</h3><p>${esc(d.travel)}</p><p class="notice">এটি campus-এর অবস্থান। তোমার Exam Centre অন্য জায়গায়ও হতে পারে। Admit Card ও Seat Plan-এর ঠিকানা অনুযায়ী যাত্রা ঠিক করো; map search-এর pin-ও মিলিয়ে নাও।</p><h3>Stay & Budget</h3><p>${esc(d.stay)}</p></section><section id="admission-process"><h2>Admission Overview</h2><span class="tag">${esc(d.session)}</span><p>${esc(d.overview)}</p>${d.facts?.length?`<dl class="campus-facts">${d.facts.map(([h,t])=>`<div><dt>${esc(h)}</dt><dd>${esc(t)}</dd></div>`).join('')}</dl>`:''}<h3>Eligibility & Exam Pattern</h3><p>${esc(d.eligibility)}</p><h3>Application → Enrolment</h3><ol>${d.process.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section><section id="documents"><h2>Documents Checklist</h2><p>নিচের তালিকাটি প্রস্তুতির জন্য। কোন document কখন লাগবে এবং upload size কত হবে, session-এর নির্দেশনা থেকে মিলাও।</p><ul>${d.documents.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>After the Result</h3><p>Merit position পেলেই ভর্তি শেষ নয়। Subject Choice, প্রয়োজন হলে interview বা practical, document verification, fee ও final admission-এর notice অনুসরণ করো। Migration বা waiting list-এর নিয়ম সংশ্লিষ্ট notice থেকে পড়ো।</p></section><section id="official-sources"><h2>Official Sources</h2><p class="muted">Reviewed: ${date(d.reviewed)} · Session: ${esc(d.session)}</p><div class="source-list">${d.sources.map(x=>external(x.url,x.label)).join('')}</div><div class="actions">${external(u.url,'Admission Resource ↗')}${external(u.site,'University Website ↗')}</div></section></article><div class="actions"><button class="btn secondary" data-save="university/${u.id}">${savedLabel('university/'+u.id)}</button><a class="btn" href="#practice">Practice English →</a></div></div>`)}
function updates(){return wrap(heading('Admission Updates','আবেদন করার আগে official notice পড়ো। এই বিভাগ resource directory; live news feed নয়।','OFFICIAL RESOURCES')+`<div class="notice">Resource links যাচাই: ${date(C.updated)}। নতুন session-এর circular, deadline বা result আমরা স্বয়ংক্রিয়ভাবে সংগ্রহ করি না। Portal-এ session এবং notice-এর প্রকাশের তারিখ মিলিয়ে নাও।</div><div class="grid">${C.updates.map(updateCard).join('')}</div><section class="section"><div class="notice">তারিখ, যোগ্যতা, fee বা unit-এর নিয়ম বদলাতে পারে। চূড়ান্ত তথ্যের জন্য সংশ্লিষ্ট বিশ্ববিদ্যালয়ের বর্তমান official notice দেখো।</div></section>`)}
function practice(){return wrap(heading('English MCQ Test','নাম, topic ও প্রশ্নসংখ্যা বেছে test শুরু করো। Submit করলে answer key, ব্যাখ্যা ও সময় দেখাবে।','ENGLISH PRACTICE')+practiceSetup()+leaderboardPanel())}
async function registerStudentProfile(){const name=$('player-name')?.value.trim()||'',avatar=$('player-avatar')?.value||data.player?.avatar||'🚂';if(name.length<2){toast('নিজের পুরো নাম লিখো—কমপক্ষে ২টি অক্ষর।');$('player-name')?.focus();return false}try{const response=await fetch('/api/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({playerId:data.player?.playerId||undefined,name,avatar})});const result=await response.json();if(!response.ok||!result.ok||!result.player?.playerId)throw new Error(result.error||'Profile registration failed');data.player={...result.player,roll:''};persist();try{localStorage.setItem('campus-player',JSON.stringify(data.player))}catch{}toast('✅ নাম database-এ save হয়েছে। আবার এলে নামটি দেখাবে।');if(location.hash==='#practice')render(false);return true}catch(error){toast('⚠️ নাম database-এ save হয়নি। Internet/database connection check করে আবার চেষ্টা করো।');return false}}
async function restoreStudentProfile(){try{const id=data.player?.playerId;const url=id?`/api/profile?playerId=${encodeURIComponent(id)}`:'/api/profile';const response=await fetch(url,{cache:'no-store'});const result=await response.json();if(response.ok&&result.ok&&result.player?.playerId){data.player={...result.player,roll:''};persist();try{localStorage.setItem('campus-player',JSON.stringify(data.player))}catch{}const currentRoute=(location.hash.slice(1)||'home').split('/')[0];if(['home','practice'].includes(currentRoute))render(false)}}catch{/* Keep the last locally saved name available while offline. */}}
function shuffle(a){return a.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v)}
async function startSession(mode,topic,count){if(data.session&&!confirm('নতুন session শুরু করলে অসমাপ্ত session বদলে যাবে। শুরু করবে?'))return;const qs=shuffle(QB.filter(q=>topic==='all'||q.topic===topic)).slice(0,count);if(!qs.length){toast('এই topic-এ প্রশ্ন পাওয়া যায়নি।');return}const session={mode,topic,ids:qs.map(q=>q.id),answers:{},started:Date.now(),deadline:mode==='test'?Date.now()+qs.length*60000:null,attemptId:mode==='fun'?`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,12)}`:undefined};if(['fun','test'].includes(mode)){const name=$('player-name')?.value.trim()||data.player?.name||'',avatar=data.player?.avatar||'🚂';if(name.length<2){toast('Leaderboard-এর জন্য আগে নিজের পুরো নাম লিখো।');$('player-name')?.focus();return}let profile=data.player||{};if(!profile.playerId||profile.name!==name||profile.avatar!==avatar){const ok=await registerStudentProfile();if(!ok)return;profile=data.player||{}}if(!profile.playerId){toast('Student profile পাওয়া যায়নি। আবার নাম save করো।');return}session.player={playerId:profile.playerId,name:profile.name,avatar:profile.avatar||'🚂',roll:''};if(mode==='fun'){session.index=0;session.score=0;session.streak=0;session.bestStreak=0;session.pointsByQuestion={};session.timeouts=[];session.hiddenOptions={};session.fifty=true;session.freeze=true;session.frozen=false;session.deadline=Date.now()+30000;}data.player=session.player;try{localStorage.setItem('campus-player',JSON.stringify(data.player))}catch{}}data.session=session;persist();location.hash='session';if(location.hash==='#session')render()}
function sessionQuestions(s){return s.ids.map(id=>QB.find(q=>q.id===id)).filter(Boolean)}
function explanationBn(q){if(q.topic==='Article'){if(/[\u0980-\u09FF]/.test(q.e))return q.e;const t=(q.q+' '+q.e).toLowerCase();if(/nile|river|source/.test(t))return 'নির্দিষ্ট নদীর নাম এবং তার নির্দিষ্ট উৎস বোঝাতে “the” ব্যবহার হয়।';if(/flute|musical instrument/.test(t))return 'বাদ্যযন্ত্র বাজানোর কথা বললে সাধারণত instrument-এর আগে “the” বসে।';if(/love|abstract noun/.test(t))return 'সাধারণ অর্থে abstract noun “love”-এর আগে article লাগে না; “a beautiful thing” singular countable noun phrase।';if(/rainbow|secondary/.test(t))return 'একটি অনির্দিষ্ট singular countable noun-এর আগে “a” বসে।';if(/artist|relative clause|specific book|book i bought|you bought yesterday/.test(t))return 'যে clause বা context noun-টিকে নির্দিষ্ট করে, তার আগে “the” বসে।';if(/outstanding|vowel sound/.test(t))return '“Outstanding” vowel sound দিয়ে শুরু, তাই “an”; নির্দিষ্ট উপাধি “the Perfect Man”।';if(/physicist|named physicist/.test(t))return 'নির্দিষ্ট ব্যক্তিকে পদবিসহ বোঝানো হয়েছে, তাই “the physicist”।';if(/bull by the horns|idiom/.test(t))return '“Take the bull by the horns” একটি fixed idiom; এখানে দুটো জায়গাতেই “the” লাগে।';if(/few mistakes|a few/.test(t))return '“A few” মানে কিছু/কয়েকটি; “few” একা হলে অর্থ বেশি নেতিবাচক হয়।';if(/diet|sugar/.test(t))return 'প্রচলিত phrase হলো “on a diet”; সাধারণ uncountable noun “sugar”-এর আগে article লাগে না।';if(/tiger|endangered species/.test(t))return 'একটি শ্রেণির প্রতিনিধিত্বে “a tiger”, vowel sound-এ “an endangered species”, আর নির্দিষ্ট বিষয় বোঝাতে “the urgency”।';if(/confidence|expert/.test(t))return '“The confidence” নির্দিষ্টভাবে “of an expert” দিয়ে চিহ্নিত; “expert” vowel sound দিয়ে শুরু, তাই “an”।';if(/uncanny|skill/.test(t))return '“Uncanny” vowel sound দিয়ে শুরু, তাই “an”; “skill” একটি singular countable noun, তাই “a”।';if(/wisdom|of the man/.test(t))return '“Of the man” phrase-টি wisdom-কে নির্দিষ্ট করেছে, তাই abstract noun হলেও “the” বসে।';if(/appointed|appoint/.test(t))return 'appoint/elect/make-এর পরে পদ বা role complement হিসেবে এলে সাধারণত article বাদ যায়: “appointed head”।';if(/hospital|heart attack/.test(t))return 'British usage-এ চিকিৎসার উদ্দেশ্যে “go to hospital” বলা হয়; “heart attack” singular count noun, তাই “a”।';if(/elderly/.test(t))return '“The + adjective” কোনো শ্রেণির মানুষ বোঝায়: “the elderly” মানে বয়স্ক মানুষজন।';if(/aunt|home for/.test(t))return '“Aunt” vowel sound দিয়ে শুরু বলে “an”; “a home”; আর শ্রেণি বোঝাতে “the elderly”।';if(/shakespeare|rabindranath|nazrul/.test(t))return 'কোনো বিখ্যাত ব্যক্তির মতো গুণ/প্রতিভা বোঝালে proper name-এর আগে “a” বসতে পারে।';if(/european|university|unique/.test(t))return 'বানান vowel দিয়ে শুরু হলেও উচ্চারণ /j/ consonant sound হলে “a” বসে—যেমন a European, a university, a unique chance।';if(/earthquake|precautions/.test(t))return '“Earthquake” vowel sound দিয়ে শুরু, তাই “an”; নির্দিষ্ট প্রয়োজনীয় সতর্কতা বোঝাতে “the necessary precautions”।';if(/only day|only makes/.test(t))return '“Only” একমাত্র বোঝালে noun phrase নির্দিষ্ট হয়, তাই “the only day”।';if(/hour|silent/.test(t))return '“Hour”-এর h উচ্চারিত হয় না; vowel sound দিয়ে শুরু হওয়ায় “an hour”।';if(/plates|ashtrays/.test(t))return 'নির্দিষ্ট plate বোঝালে “the plates”; generic plural “ashtrays”-এর আগে article লাগে না।';if(/upper floor|french/.test(t))return 'নির্দিষ্ট মানুষ ও নির্দিষ্ট floor বোঝাতে “the” বসে; natural English-এ “on the upper floor” বলা হয়।';if(/better of|two/.test(t))return 'দুটির মধ্যে একটি বেছে নিতে “the better of the two” ব্যবহার হয়।';if(/mahabharata|greatest epic/.test(t))return 'Epic-এর নাম “the Mahabharata”; superlative “greatest”-এর আগেও “the” বসে।';if(/miles|band/.test(t))return 'এখানে band-এর proper name “Miles”; cross-check অনুযায়ী সাধারণ ব্যবহারে article ছাড়াই লেখা হয়।';if(/hockey|sport/.test(t))return 'খেলার নাম সাধারণভাবে ব্যবহার করলে article লাগে না: “hockey”।';if(/canada|usa/.test(t))return 'Canada-এর আগে article লাগে না, কিন্তু “the USA” বলা হয়।';if(/amazon|longest river/.test(t))return 'Superlative “longest”-এর আগে “the”; মহাদেশের নাম “South America”-এর আগে article লাগে না।';if(/phd/.test(t))return '“PhD” উচ্চারণে /p/ consonant sound দিয়ে শুরু, তাই “a PhD holder”।';if(/apple|you ate/.test(t))return '“You ate” clause-টি নির্দিষ্ট apple বোঝায়, তাই “the apple”।';if(/king|once upon/.test(t))return 'গল্পে প্রথমবার অনির্দিষ্ট একজন king পরিচয় করানো হয়েছে, তাই “a king”।';return 'Article বাছতে noun নির্দিষ্ট কি না, countable কি না এবং শব্দের প্রথম উচ্চারণ vowel sound দিয়ে শুরু কি না দেখো।'} const tips={'Tense':'বাক্যে yesterday, since, by the time বা when-এর মতো সময়ের ইঙ্গিত দেখে verb-এর সঠিক tense বেছে নাও।','Sequence of Tense':'Reporting verb ও ঘটনার সময়ের সম্পর্ক দেখে tense নির্বাচন করো; সব ক্ষেত্রে tense বদলায় না।','Mixed English':'বাক্যের অর্থ, grammar rule ও শব্দের ব্যবহার মিলিয়ে উত্তরটি বোঝো।','Noun':'Noun countable না uncountable, singular না plural—এগুলো দেখো।','Number':'Singular/plural এবং irregular plural-এর নিয়ম মিলিয়ে নাও।','Gender':'শব্দটির প্রচলিত gender form ও বাক্যের context যাচাই করো।'};return tips[q.topic]||'বাক্যের অর্থ ও grammar rule মিলিয়ে সঠিক উত্তরটি বোঝো.'}
function questionView(q,i,s,review=false){const raw=s.answers[q.id],choice=Number.isInteger(raw)&&raw>=0&&raw<=3?raw:null,answered=choice!==null,expired=(s.timeouts||[]).includes(q.id),show=review||(s.mode==='learn'&&answered)||(s.mode==='fun'&&(answered||expired)),hidden=(s.hiddenOptions&&s.hiddenOptions[q.id])||[];return `<article class="question ${s.mode==='fun'?'fun-question':''}" id="question-${q.id}"><div class="qmeta"><span>প্রশ্ন ${bn(i+1)} · ${esc(q.topic)}</span><span>${esc(q.source)}</span></div><h3 lang="en">${esc(q.q)}</h3><div class="options" lang="en">${q.o.map((o,j)=>{const gone=s.mode==='fun'&&hidden.includes(j)&&!show;return `<button class="option ${choice===j?'selected':''} ${show&&j===q.a?'correct':''} ${show&&choice===j&&j!==q.a?'wrong':''} ${gone?'fun-gone':''}" data-answer="${q.id}" data-choice="${j}" ${show||gone?'disabled':''}><span>${'ABCD'[j]}</span><span>${esc(o)}${show&&j===q.a?' ✓':''}${show&&choice===j&&j!==q.a?' ✕':''}</span></button>`}).join('')}</div>${show?`<div class="feedback ${answered&&choice===q.a?'feedback-win':''}" lang="en"><b>${expired?'⏰ Time up!':choice===null?'Not answered':choice===q.a?'✅ Correct answer': '💡 Review this answer'}${s.mode==='fun'&&choice===q.a?` · +${bn(s.pointsByQuestion?.[q.id]||0)} points`:''}</b><p>${esc(q.e)}</p><p class="explanation-bn"><b>সহজ বাংলায়:</b> ${esc(explanationBn(q))}</p></div>`:''}</article>`}
function session(){const s=data.session;if(!s)return wrap(heading('কোনো অসমাপ্ত session নেই','')+'<a class="btn" href="#practice">নতুন practice শুরু করো</a><div class="section"></div>');const qs=sessionQuestions(s);if(s.mode==='fun'){const i=Math.min(s.index||0,qs.length-1),q=qs[i],answered=Number.isInteger(s.answers[q.id])&&s.answers[q.id]>=0,expired=(s.timeouts||[]).includes(q.id),finishedQuestion=answered||expired,mult=s.streak>=5?2:s.streak>=3?1.5:1;return wrap(heading('🎮 Fun MCQ Challenge',s.topic==='all'?'সব English topic':s.topic,'PLAY · EARN POINTS · KEEP YOUR STREAK')+`<div class="fun-shell"><div class="fun-player"><span class="fun-avatar">${esc(s.player.avatar||'🚂')}</span><div><b>${esc(s.player.name)}</b><small>Registered student · ${esc(s.topic==='all'?'Mixed English':s.topic)}</small></div><button class="chip" id="fun-sound" type="button">${funMuted?'🔇 Sound off':'🔊 Sound on'}</button></div><div class="fun-hud"><div><small>QUESTION</small><b>${bn(i+1)} / ${bn(qs.length)}</b></div><div><small>SCORE</small><b id="fun-score">${bn(s.score||0)}</b></div><div><small>STREAK</small><b id="fun-streak">${bn(s.streak||0)} 🔥</b></div><div><small>MULTIPLIER</small><b id="fun-mult">x${mult}</b></div><div><small>TIME LEFT</small><b id="fun-timer" class="fun-timer">${finishedQuestion?'—':s.frozen?'🧊':Math.max(0,Math.ceil(((s.deadline||Date.now()+30000)-Date.now())/1000))+'s'}</b></div></div><div class="fun-progress"><span style="width:${((i+(finishedQuestion?1:0))/qs.length)*100}%"></span></div><div class="fun-lifelines"><button class="btn secondary" data-fun-life="fifty" ${!s.fifty||finishedQuestion?'disabled':''}>✂️ 50:50 ${s.fifty?'(1 left)':'(used)'}</button><button class="btn secondary" data-fun-life="freeze" ${!s.freeze||finishedQuestion?'disabled':''}>🧊 Freeze Timer ${s.freeze?'(1 left)':'(used)'}</button><span>${s.streak>=5?'🔥 ON FIRE! x2 bonus':s.streak>=3?'⚡ STREAK BONUS x1.5':'প্রতি সঠিক উত্তরে +10 থেকে +20 পয়েন্ট'}</span></div>${questionView(q,i,s)}<div class="fun-bottom">${finishedQuestion?`<div class="fun-reaction ${answered&&s.answers[q.id]===q.a?'good':'bad'}">${expired?'সময় শেষ—পরের প্রশ্নে চলো!':answered&&s.answers[q.id]===q.a?(s.streak>=5?'🔥 অন ফায়ার! ডাবল পয়েন্ট!':s.streak===3?'হ্যাট্রিক! x1.5 bonus 🔥':'জোস! সঠিক উত্তর 🎯'):'ভুল হয়েছে, শেখাও হয়েছে 😌'}</div><button class="btn fun-start" id="fun-next">${i===qs.length-1?'🏁 ফলাফল ও leaderboard':'পরের প্রশ্ন →'}</button>`:`<p class="fun-hint">⏳ ৩০ সেকেন্ডের মধ্যে উত্তর দাও। কিবোর্ডে A/B/C/D-ও ব্যবহার করতে পারো।</p>`}<button class="btn plain" id="fun-end">এখনই শেষ করো</button></div></div>`)}return wrap(heading(s.mode==='test'?'English model practice':'উত্তর বুঝে practice করো',s.topic==='all'?'সব English topic':s.topic,'YOUR STUDY SESSION')+`<div class="test-bar"><div><b id="answer-count">${bn(Object.keys(s.answers).length)} / ${bn(qs.length)}</b> উত্তর${s.mode==='test'?' · <span class="timer" id="timer"></span>':''}</div><button class="btn" id="finish-session">${s.mode==='test'?'সব উত্তর জমা দাও':'সব উত্তর জমা দিয়ে review করো'}</button></div>${qs.map((q,i)=>questionView(q,i,s)).join('')}<div class="section"><button class="btn" id="finish-bottom">সব উত্তর জমা দিয়ে ফল দেখো →</button></div>`)}
async function finishSession(auto=false){const s=data.session;if(!s)return;if(s.mode==='fun'){const qs=sessionQuestions(s);if(!auto&&s.index<qs.length-1&&!(s.finishedByUser&&confirm('খেলা শেষ করতে চাও? এখন বাকি প্রশ্নগুলোর উত্তর না দিলেও result জমা হবে.')))return;if(!auto&&s.index<qs.length-1&&!s.finishedByUser)return;}else if(!auto&&Object.keys(s.answers).length<s.ids.length&&!confirm('কিছু প্রশ্নের উত্তর দেওয়া হয়নি। সব উত্তর submit করলে answer key ও explanation দেখা যাবে। এখনই submit করবে?'))return;const qs=sessionQuestions(s),correct=qs.filter(q=>s.answers[q.id]===q.a).length,finished=Date.now(),attempt={...s,attemptId:s.attemptId||`${finished.toString(36)}-${Math.random().toString(36).slice(2,12)}`,finished,correct,total:qs.length,timeSec:Math.max(0,Math.round((finished-s.started)/1000))};delete attempt.deadline;data.attempts.unshift(attempt);data.attempts=data.attempts.slice(0,30);data.session=null;persist();if(['fun','test'].includes(s.mode)&&s.player?.playerId){attempt.leaderboardStatus='saving';data.attempts[0].leaderboardStatus='saving';persist();try{const response=await fetch('/api/scores',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({playerId:s.player.playerId,attemptId:attempt.attemptId,topic:s.topic,score:Math.round(correct/qs.length*100),correct,total:qs.length,bestStreak:s.bestStreak||0,timeSec:attempt.timeSec,mode:s.mode})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Server rejected score');attempt.leaderboardStatus='saved';data.attempts[0].leaderboardStatus='saved';toast('✅ Score MongoDB-তে save হয়েছে এবং leaderboard update হয়েছে!');}catch(err){attempt.leaderboardStatus='local';data.attempts[0].leaderboardStatus='local';data.attempts[0].leaderboardError=String(err.message||err).slice(0,160);toast('⚠️ Score server-এ save হয়নি; result এই device-এ আছে। পরে আবার save চেষ্টা করো।')}persist()}location.hash='result';if(location.hash==='#result')render();if(auto&&s.mode==='test')toast('সময় শেষ হয়েছে। তোমার উত্তর জমা হয়েছে।')}
function result(){const a=data.attempts[0];if(!a)return missing();const isFun=a.mode==='fun',accuracy=Math.round(a.correct/a.total*100),points=isFun?`<div class="stat"><b>${bn(a.score||0)}</b><small>মোট game points</small></div>`:'';const saveNote=(isFun||a.mode==='test')?(a.leaderboardStatus==='saved'?'<div class="notice save-success" id="score-save-state">✅ তোমার score global leaderboard-এ save হয়েছে।</div>':a.leaderboardStatus==='local'?`<div class="notice save-warning" id="score-save-state">⚠️ Global leaderboard-এ save হয়নি। এই device-এ result আছে।<button class="btn secondary" id="retry-score">আবার save করার চেষ্টা</button></div>`:'<div class="notice" id="score-save-state">Score save status যাচাই হচ্ছে…</div>'):'';return wrap(heading(isFun?'🏁 Fun Challenge Result':'আজকের practice-এর ফল','একটি score নয়, পরের পড়ার জন্য একটি পথ।','YOUR REVIEW')+`${isFun?`<div class="fun-result-head"><span>${esc(a.player?.avatar||'🚂')}</span><div><h2>${esc(a.player?.name||'Student')}</h2><p>Student profile saved in your browser and database</p></div><div class="fun-result-points">${bn(a.score||0)}<small>POINTS</small></div></div>`:''}<div class="stats">${points}<div class="stat"><b>${bn(a.correct)}/${bn(a.total)}</b><small>সঠিক উত্তর</small></div><div class="stat"><b>${bn(accuracy)}%</b><small>Accuracy</small></div><div class="stat"><b>${bn(Math.floor((a.timeSec||0)/60))}m ${bn((a.timeSec||0)%60)}s</b><small>সময় লেগেছে</small></div><div class="stat"><b>${bn(a.total-Object.keys(a.answers||{}).length)}</b><small>উত্তর দেওয়া হয়নি</small></div></div>${saveNote}<div class="actions" style="margin-bottom:25px"><a class="btn" href="#practice">আবার practice করো →</a><a class="btn secondary" href="#saved">সব ফল দেখো</a></div>${(isFun||a.mode==='test')?'<section class="section"><div class="section-head"><div><h2>🏆 এই topic-এর leaderboard</h2><p>এই topic-এ তোমার অবস্থান ও অন্যদের best score।</p></div><button class="btn secondary" id="leaderboard-refresh">Refresh</button></div><div id="global-leaderboard" data-topic="'+esc(a.topic)+'" data-player-id="'+esc(data.player?.playerId||a.player?.playerId||'')+'"><div class="empty">Leaderboard load হচ্ছে…</div></div></section>':''}${sessionQuestions(a).map((q,i)=>questionView(q,i,a,true)).join('')}`)}
function savedLabel(id){return data.saved.includes(id)?'পড়ার তালিকা থেকে সরাও':'পড়ার তালিকায় রাখো +'}
function saved(){const links=data.saved.map(id=>{let [kind,key]=id.split('/');const x=kind==='university'?C.universities.find(u=>u.id===key):null;return x?`<div class="history-row"><a href="#${esc(id)}">${esc(x.title||x.name)} →</a><button class="chip" data-save="${esc(id)}">সরাও</button></div>`:''}).join('');return wrap(heading('তোমার নিজের পড়ার জায়গা','তোমার checklist ও নতুন website-এর practice results এই browser-এ থাকে। কোনো নাম, roll বা phone number প্রয়োজন নেই।','MY STUDY SPACE')+(!storageOK?'<div class="notice">Browser storage ব্যবহার করা যাচ্ছে না। Backup download করে রাখো।</div>':'')+`<section class="section"><h2 style="margin-bottom:20px">পড়ার ছোট routine</h2><div class="grid"><article class="card"><h3>Daily lecture</h3><p>আজকের class lecture আজই শেষ করো।</p></article><article class="card"><h3>Revision</h3><p>গতকালের পড়া প্রতিদিন আবার দেখো।</p></article><article class="card"><h3>Previous questions</h3><p>আগের বছরের MCQ solve করে pattern ও ভুল চিহ্নিত করো।</p></article><article class="card"><h3>Timed practice</h3><p>সময় ধরে answer দাও এবং explanation পড়ে ভুল বুঝে নাও।</p></article></div></section><section class="section"><h2 style="margin-bottom:20px">পরে পড়বে</h2>${links||'<div class="empty">Guide বা university profile-এর “পড়ার তালিকায় রাখো” button ব্যবহার করো।</div>'}</section><section class="section"><h2 style="margin-bottom:20px">সাম্প্রতিক practice</h2>${data.attempts.length?data.attempts.slice(0,10).map(a=>`<div class="history-row"><div>${date(a.finished)} · ${esc(a.topic==='all'?'Mixed topics':a.topic)}<br><small class="muted">${a.mode==='test'?'Timed model practice':a.mode==='fun'?'Fun Challenge · '+bn(a.score||0)+' points':'Learning practice'}</small></div><b>${bn(a.correct)}/${bn(a.total)}</b></div>`).join(''):'<div class="empty">প্রথম practice শেষ করলে এখানে ফল দেখতে পাবে।</div>'}</section><section class="section"><h2 style="margin-bottom:16px">Backup ও privacy</h2><p class="muted">Saved items, checklist ও local practice history এই browser-এ থাকে। Fun Challenge-এর নাম, roll ও score global leaderboard-এর জন্য server-side save হয়। এই project কোনো password বা account credential চায় না। Backup download করে local progress অন্য device-এ নিতে পারো।</p><div class="actions" style="margin-top:20px"><button class="btn secondary" id="export-data">Backup download</button><label class="btn secondary" for="import-data">Backup import</label><input id="import-data" type="file" accept=".json" hidden><button class="btn plain" id="clear-data">এই browser-এর data মুছুন</button></div></section>`)}
function about(){return wrap(`<div class="reading">${heading('আমাদের কথা ও তথ্যের উৎস','ভর্তি প্রস্তুতির English practice, fun quiz এবং বিশ্ববিদ্যালয় পরিচিতি।','ABOUT THIS PROJECT')}<article><h2>কার জন্য এই website?</h2><p>বিশ্ববিদ্যালয় ভর্তি পরীক্ষার্থীদের জন্য free practice resource। মূল CU English Lab-এর ${bn(QB.length)}টি প্রশ্ন, source labels ও explanations রাখা হয়েছে; প্রশ্নগুলো topic অনুযায়ী practice ও timed model session-এ ব্যবহার করা হয়। Source label থাকলেই সেটি সম্পূর্ণ official paper—এমন দাবি করা হচ্ছে না।</p><h2>প্রশ্ন ও তথ্যের নির্ভরযোগ্যতা</h2><p>English question bank-এ original practice items এবং source-labelled items রয়েছে। Admission deadline, fee, eligibility বা seat count-এর মতো তথ্যের জন্য বর্তমান official circular-ই চূড়ান্ত।</p><h2>Practice ও privacy</h2><p>Saved items, checklist ও সাধারণ practice results এই browser-এ থাকে। Embedded Fun Challenge-এর student name, roll, score, accuracy, best streak ও time private Vercel Blob-এ server-side save হয়; global leaderboard-এ প্রতি roll-এর best score দেখানো হয়।</p><h2>University sources</h2><ul>${C.universities.map(u=>`<li>${esc(u.name)}<br>${external(u.url,'Official resource')}</li>`).join('')}</ul><p class="muted" style="margin-top:25px">Content review: ${date(C.updated)}</p></article><div class="section"></div></div>`)}
function more(){return wrap(heading('আরও কিছু দরকারি জায়গা','')+`<div class="grid">${[...paths,['saved','তোমার অগ্রগতি','Checklist, saved university ও result'],['about','আমাদের কথা','তথ্য, source ও privacy']].map(p=>`<a class="card" href="#${p[0]}"><h3>${p[1]}</h3><p>${p[2]}</p><span class="text-link">খুলুন →</span></a>`).join('')}<a class="card" href="#practice"><h3>🎮 Fun MCQ Challenge</h3><p>Timer, streak bonus, lifelines, sound and leaderboard—all inside the question bank.</p><span class="text-link">Play game →</span></a></div><div class="section"></div>`)}
function missing(){return wrap(heading('এই পাতাটি পাওয়া যায়নি','অন্য কোনো বিভাগ থেকে শুরু করো।')+'<a class="btn" href="#home">হোমে ফিরে যাও</a><div class="section"></div>')}
function render(scroll=true){clearInterval(timerID);const route=(location.hash.slice(1)||'home').split('/');const pages={home,universities,university:()=>university(route[1]),updates,practice,session,result,saved,about,more};$('main').innerHTML=(pages[route[0]]||missing)();document.title=(route[0]==='home'?'ক্যাম্পাস পথে · Admission Companion':$('main').querySelector('h1')?.textContent+' · ক্যাম্পাস পথে');document.querySelectorAll('nav a').forEach(a=>{const target=a.getAttribute('href').slice(1);let active=target===route[0]||(target==='universities'&&route[0]==='university')||(target==='practice'&&['session','result'].includes(route[0]))||(target==='more'&&['updates','saved','about'].includes(route[0]));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(scroll)window.scrollTo(0,0);if(route[0]==='session'&&data.session?.mode==='test'){tick();if(data.session)timerID=setInterval(tick,1000)}else if(route[0]==='session'&&data.session?.mode==='fun'){tick();if(data.session)timerID=setInterval(tick,500)}if(route[0]==='practice'||route[0]==='result')loadGlobalLeaderboard()}
function tick(){const s=data.session;if(!s)return;if(s.mode==='fun'){const q=sessionQuestions(s)[s.index||0];if(!q||Number.isInteger(s.answers[q.id])||(s.timeouts||[]).includes(q.id)||s.frozen)return;const remaining=Math.ceil((s.deadline-Date.now())/1000);if(remaining<=0){clearInterval(timerID);timeoutFunQuestion();return}const el=$('fun-timer');if(el){el.textContent=remaining+'s';el.classList.toggle('urgent',remaining<=8)}return}if(s.mode!=='test')return;const remaining=Math.ceil((s.deadline-Date.now())/1000);if(remaining<=0){clearInterval(timerID);finishSession(true);return}if($('timer'))$('timer').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`}
let funMuted=false,funAudio=null;try{funMuted=localStorage.getItem('campus-fun-muted')==='true'}catch{}
function funBeep(kind='good'){if(funMuted)return;try{funAudio=funAudio||new (window.AudioContext||window.webkitAudioContext)();const notes=kind==='bad'?[320,220]:kind==='combo'?[660,880,1175]:[660,880];let at=funAudio.currentTime;for(const hz of notes){const o=funAudio.createOscillator(),g=funAudio.createGain();o.type='triangle';o.frequency.value=hz;g.gain.setValueAtTime(.10,at);g.gain.exponentialRampToValueAtTime(.001,at+.13);o.connect(g);g.connect(funAudio.destination);o.start(at);o.stop(at+.14);at+=.1}}catch{}}
function funCelebrate(emoji='⭐'){if(typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<10;i++){const node=document.createElement('span');node.className='fun-rain';node.textContent=emoji;node.style.left=(Math.random()*96)+'vw';node.style.animationDelay=(Math.random()*.5)+'s';document.body.appendChild(node);setTimeout(()=>node.remove(),2200)}}
function bestBoardRows(rows){const map=new Map();for(const entry of rows||[]){const key=String(entry.playerId||entry.roll||entry.name||'').trim().toLowerCase()+'::'+String(entry.topic||'all');if(!key)continue;const old=map.get(key);if(!old){map.set(key,{...entry,attempts:Number(entry.attempts)||1});continue}const attempts=(Number(old.attempts)||1)+(Number(entry.attempts)||1);if(Number(entry.score)>Number(old.score)||(Number(entry.score)===Number(old.score)&&Number(entry.timeSec)<Number(old.timeSec)))map.set(key,{...entry,attempts});else old.attempts=attempts}return [...map.values()].sort((a,b)=>Number(b.score)-Number(a.score)||Number(b.correct)-Number(a.correct)||Number(a.timeSec)-Number(b.timeSec))}
async function loadGlobalLeaderboard(){const target=$('global-leaderboard');if(!target)return;target.innerHTML='<div class="empty">Leaderboard load হচ্ছে…</div>';try{const res=await fetch('/api/scores',{cache:'no-store'}),payload=await res.json();if(!res.ok||!payload.ok)throw new Error(payload.error||'API error');let rows=bestBoardRows(payload.rows||[]);const wanted=target.dataset.topic;if(wanted&&wanted!=='all')rows=rows.filter(r=>r.topic===wanted);if(!rows.length){target.innerHTML='<div class="empty">এখনো কোনো score নেই। প্রথম English test দিয়ে leaderboard শুরু করো!</div>';return}const top=[...rows].sort((a,b)=>(b.score||0)-(a.score||0)||(b.correct||0)-(a.correct||0))[0];const myId=target.dataset.playerId;const myRank=myId?rows.findIndex(r=>r.playerId===myId)+1:0;const displayRows=(()=>{if(wanted&&wanted!=='all')return rows;const map=new Map();for(const r of rows){const k=String(r.playerId||r.name).toLowerCase(),old=map.get(k);if(!old)map.set(k,{...r});else{old.attempts=(Number(old.attempts)||1)+(Number(r.attempts)||1);if(Number(r.score)>Number(old.score))Object.assign(old,{score:r.score,correct:r.correct,total:r.total,topic:r.topic})}}return [...map.values()].sort((a,b)=>b.score-a.score||b.correct-a.correct)})();const most=(()=>{if(wanted&&wanted!=='all')return [...rows].sort((a,b)=>(b.attempts||1)-(a.attempts||1)||(b.score||0)-(a.score||0))[0];const totals=new Map();for(const r of rows){const k=String(r.playerId||r.name).toLowerCase(),old=totals.get(k)||{...r,attempts:0};old.attempts+=Number(r.attempts)||1;if(Number(r.score)>Number(old.score))Object.assign(old,{score:r.score,correct:r.correct,total:r.total,topic:r.topic});totals.set(k,old)}return [...totals.values()].sort((a,b)=>b.attempts-a.attempts||b.score-a.score)[0]})();target.innerHTML=`${myRank?`<div class="notice">এই topic-এ তোমার অবস্থান: <b>${bn(myRank)}তম</b> · ${bn(rows[myRank-1].score||0)} score</div>`:''}<div class="board-highlights"><article class="board-highlight"><span>🥇 সর্বোচ্চ score</span><b>${esc(top.name||'Student')}</b><strong>${bn(top.score||0)}<small> score</small></strong><small>${bn(top.correct||0)}/${bn(top.total||0)} সঠিক</small></article><article class="board-highlight"><span>🔥 সবচেয়ে বেশি test</span><b>${esc(most.name||'Student')}</b><strong>${bn(most.attempts||1)} <small>tests</small></strong><small>বারবার practice করে এগিয়ে</small></article></div><div class="global-board">${displayRows.slice(0,5).map((e,i)=>`<div class="global-board-row"><b class="global-rank">${['🥇','🥈','🥉'][i]||i+1}</b><span class="global-avatar">${esc(e.avatar||'🚂')}</span><div class="global-name"><b>${esc(e.name||'Student')}</b><small>${bn(e.correct||0)}/${bn(e.total||0)} correct · ${bn(e.attempts||1)} tests</small></div><strong>${bn(e.score||0)}<small> score</small></strong></div>`).join('')}</div>`;}catch{target.innerHTML='<div class="notice">Leaderboard এখন load হচ্ছে না। পরে আবার চেষ্টা করো।</div>'}}
function funNext(){const s=data.session;if(!s||s.mode!=='fun')return;const qs=sessionQuestions(s);if((s.index||0)>=qs.length-1){finishSession();return}s.index++;s.deadline=Date.now()+30000;s.frozen=false;s.hiddenOptions={...(s.hiddenOptions||{})};persist();render(false);window.scrollTo({top:0,behavior:'smooth'})}
function timeoutFunQuestion(){const s=data.session;if(!s||s.mode!=='fun')return;const q=sessionQuestions(s)[s.index||0];if(!q||Number.isInteger(s.answers[q.id])||(s.timeouts||[]).includes(q.id))return;s.timeouts=[...(s.timeouts||[]),q.id];s.streak=0;s.deadline=0;funBeep('bad');persist();render(false)}
async function retryScoreSave(attempt){if(!attempt||!['fun','test'].includes(attempt.mode)||!attempt.player?.playerId)return;attempt.leaderboardStatus='saving';persist();try{const response=await fetch('/api/scores',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({playerId:attempt.player.playerId,attemptId:attempt.attemptId,topic:attempt.topic,score:Math.round(attempt.correct/attempt.total*100),correct:attempt.correct,total:attempt.total,bestStreak:attempt.bestStreak||0,timeSec:attempt.timeSec||0,mode:attempt.mode})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Server rejected score');attempt.leaderboardStatus='saved';delete attempt.leaderboardError;toast('✅ Score database-এ save হয়েছে!')}catch(err){attempt.leaderboardStatus='local';attempt.leaderboardError=String(err.message||err).slice(0,160);toast('⚠️ Score এখনও server-এ save হয়নি। পরে আবার চেষ্টা করো।')}persist();render(false);loadGlobalLeaderboard()}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validBackup(d){if(!d||!Array.isArray(d.saved)||!d.saved.every(s=>typeof s==='string')||!Array.isArray(d.checks)||!d.checks.every(n=>Number.isInteger(n)&&n>=0&&n<C.checklist.length)||!Array.isArray(d.attempts)||d.attempts.length>30)return false;const validSession=s=>s&&['learn','test','fun'].includes(s.mode)&&typeof s.topic==='string'&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.length<=30&&s.ids.every(id=>QB.some(q=>q.id===id))&&new Set(s.ids).size===s.ids.length&&s.answers&&Object.entries(s.answers).every(([id,n])=>s.ids.includes(id)&&Number.isInteger(n)&&n>=0&&n<=3)&&(s.timeouts||[]).every(id=>s.ids.includes(id))&&Number.isFinite(s.started)&&(s.mode!=='test'||Number.isFinite(s.deadline)||Number.isFinite(s.finished))&&(s.mode!=='fun'||(s.player&&typeof s.player.name==='string'&&(typeof s.player.playerId==='string'||typeof s.player.roll==='string')&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length));return (!d.session||validSession(d.session))&&d.attempts.every(a=>validSession(a)&&Number.isFinite(a.finished)&&a.total===a.ids.length&&Number.isInteger(a.correct)&&a.correct>=0&&a.correct<=a.total)}
document.addEventListener('click',e=>{const action=e.target.closest('button');if(action?.id==='theme-toggle'){setTheme(themeState==='dark'?'light':'dark');return}if(action?.dataset.campusTab){campusTab=action.dataset.campusTab;render(false);document.getElementById('campus-panel')?.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('campus-tab-'+campusTab)?.focus({preventScroll:true});return}const anchor=e.target.closest('a');if(anchor?.closest('.profile-tabs')){e.preventDefault();document.getElementById(anchor.getAttribute('href').slice(1))?.scrollIntoView({behavior:'smooth',block:'start'});return}const b=e.target.closest('button');if(!b)return;if(b.dataset.save){const id=b.dataset.save;data.saved=data.saved.includes(id)?data.saved.filter(x=>x!==id):[...data.saved,id];persist();if(location.hash==='#saved')render(false);else b.textContent=savedLabel(id);toast('পড়ার তালিকা আপডেট হয়েছে')}if(b.dataset.universityFilter){universityFilter=b.dataset.universityFilter;render(false)}if(b.id==='save-player-profile')registerStudentProfile();if(b.dataset.start)startSession(b.dataset.start,$('practice-topic').value,+$('practice-count').value);if(b.dataset.topicStart)startSession('learn',b.dataset.topicStart,10);if(b.id==='leaderboard-refresh')loadGlobalLeaderboard();if(b.id==='fun-sound'){funMuted=!funMuted;try{localStorage.setItem('campus-fun-muted',String(funMuted))}catch{}b.textContent=funMuted?'🔇 Sound off':'🔊 Sound on';if(!funMuted)funBeep('good')}if(b.dataset.funLife){const s=data.session;if(!s||s.mode!=='fun')return;const qs=sessionQuestions(s),q=qs[s.index||0],answered=Number.isInteger(s.answers[q.id])||(s.timeouts||[]).includes(q.id);if(answered)return;if(b.dataset.funLife==='fifty'&&s.fifty){const wrong=shuffle([0,1,2,3].filter(n=>n!==q.a)).slice(0,2);s.hiddenOptions={...(s.hiddenOptions||{}),[q.id]:wrong};s.fifty=false;funBeep('combo');persist();render(false)}else if(b.dataset.funLife==='freeze'&&s.freeze){s.frozen=true;s.freeze=false;funBeep('combo');persist();render(false);toast('🧊 Timer freeze active—এখন উত্তর দিতে সময়ের চাপ নেই।')} }if(b.id==='fun-next')funNext();if(b.id==='fun-end'){if(confirm('এখনই result তৈরি করতে চাও? বাকি প্রশ্নগুলো unanswered থাকবে।')){const s=data.session;if(s?.mode==='fun'){s.finishedByUser=true;finishSession(true)}}}if(b.dataset.answer){const s=data.session;if(!s)return;if(s.mode==='test'&&Date.now()>=s.deadline){finishSession(true);return}if(s.mode==='learn'&&Number.isInteger(s.answers[b.dataset.answer]))return;if(s.mode==='fun'){const qs=sessionQuestions(s),q=qs[s.index||0];if(!q||q.id!==b.dataset.answer||Number.isInteger(s.answers[q.id])||(s.timeouts||[]).includes(q.id)||(s.deadline&&Date.now()>=s.deadline&&!s.frozen)){if(s.deadline&&Date.now()>=s.deadline&&!s.frozen)timeoutFunQuestion();return}const choice=+b.dataset.choice,left=s.frozen?30:Math.max(0,(s.deadline-Date.now())/1000);s.answers[q.id]=choice;if(choice===q.a){s.streak=(s.streak||0)+1;s.bestStreak=Math.max(s.bestStreak||0,s.streak);const mult=s.streak>=5?2:s.streak>=3?1.5:1;const gained=Math.round((10+Math.ceil(left/3))*mult);s.pointsByQuestion={...(s.pointsByQuestion||{}),[q.id]:gained};s.score=(s.score||0)+gained;funBeep(s.streak>=3?'combo':'good');funCelebrate(s.streak>=5?'🔥':'⭐')}else{s.streak=0;funBeep('bad')}persist();render(false);return}s.answers[b.dataset.answer]=+b.dataset.choice;persist();const qs=sessionQuestions(s),index=qs.findIndex(q=>q.id===b.dataset.answer);$('question-'+b.dataset.answer).outerHTML=questionView(qs[index],index,s);$('answer-count').textContent=bn(Object.keys(s.answers).length)+' / '+bn(qs.length)}if(['finish-session','finish-bottom'].includes(b.id))finishSession();if(b.id==='retry-score')retryScoreSave(data.attempts[0]);if(b.id==='export-data')download('campus-companion-backup.json',data);if(b.id==='clear-data'&&confirm('Saved items, checklist ও practice results মুছবে? Backup আগে download করে রাখতে পারো।')){data={saved:[],checks:[],attempts:[],session:null};persist();render(false)}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.check!==undefined){const n=+el.dataset.check;data.checks=el.checked?[...new Set([...data.checks,n])]:data.checks.filter(x=>x!==n);persist();render(false)}if(el.id==='import-data'){const f=el.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const x=JSON.parse(await f.text());if(!validBackup(x))throw Error();if(confirm('এই browser-এর data backup দিয়ে replace করবে?')){data=x;persist();render(false);toast('Backup import হয়েছে')}}catch{toast('Valid Campus Companion backup দিন। Original Lab-এর backup আলাদা format।')}el.value=''}});
$('search-open').onclick=()=>{$('search-dialog').showModal();$('search-input').focus();search()};
function search(){const term=$('search-input').value.trim().toLowerCase();const all=[...C.universities.map(u=>({title:u.name,extra:u.english+' '+u.short+' '+u.text+' '+u.place+' '+u.details.division+' '+u.details.district+' '+u.details.address,url:'university/'+u.id,type:'বিশ্ববিদ্যালয়'})),...topics.map(t=>({title:t,extra:'English grammar practice',url:'practice',type:'Practice topic'})),{title:'Fun MCQ Challenge',extra:'timer streak lifelines leaderboard',url:'practice',type:'Fun game'},{title:'ভর্তি আপডেট',extra:'notice circular application official',url:'updates',type:'Official resources'}];const hits=(term?all.filter(x=>(x.title+' '+x.extra).toLowerCase().includes(term)):all.slice(0,5));$('search-results').innerHTML=hits.length?hits.map(x=>`<a class="search-hit" href="${x.external?'':'#'}${esc(x.url)}">${esc(x.title)}<small>${esc(x.type)} →</small></a>`).join(''):'<p class="empty">কিছু পাওয়া যায়নি। চবি, DU বা Article দিয়ে খুঁজে দেখো।</p>'}
$('search-input').oninput=search;$('search-results').onclick=e=>{if(e.target.closest('a'))$('search-dialog').close()};window.addEventListener('hashchange',()=>{render();$('main').focus({preventScroll:true})});window.addEventListener('pageshow',()=>{if(location.hash==='#session')tick()});if(!validBackup(data)){data={saved:[],checks:[],attempts:[],session:null}}render();restoreStudentProfile();

let themeState='light';
function setTheme(t){themeState=t==='dark'?'dark':'light';document.documentElement.dataset.theme=themeState;const toggle=$('theme-toggle');if(toggle){toggle.textContent=themeState==='dark'?'Light Mode':'Dark Mode';toggle.setAttribute('aria-label',themeState==='dark'?'Switch to light mode':'Switch to dark mode');toggle.setAttribute('aria-pressed',String(themeState==='dark'))}try{localStorage.setItem('campus-theme',themeState)}catch{}}
try{setTheme(localStorage.getItem('campus-theme')||'light')}catch{setTheme('light')}